     1→// ============================================================================
     2→// FreeLang I/O 모듈 - 파일 및 디렉토리 시스템 인터페이스
     3→// ============================================================================
     4→// 목표: Zero-Copy-DB에서 설정 파일, 벤치마크 결과, 로그 등을 읽고 쓸 수 있도록 함
     5→// 원리:
     6→//   1. 모든 파일 I/O 함수는 (value, bool) 다중 반환으로 성공/실패 구분
     7→//   2. sys_* 브리지 함수를 통해 런타임이 실제 OS 시스템 콜 오버라이드 가능
     8→//   3. 에러 코드로 근본 원인 추적 가능
     9→// 구조:
    10→//   - 에러 상수 정의
    11→//   - 데이터 구조체 (FileResult, DirEntry)
    12→//   - 경로 조작 헬퍼 (join_path, basename, dirname)
    13→//   - 내부 헬퍼 (@inline split_lines)
    14→//   - 시스템 브리지 함수 (sys_*)
    15→//   - 공개 API (read_file, write_file, append_file, file_exists, read_lines, list_dir)
    16→// ============================================================================
    17→
    18→module io {
    19→    // === 에러 코드 ===
    20→    const ERR_OK:         i32 = 0;
    21→    const ERR_NOT_FOUND:  i32 = 1;
    22→    const ERR_PERMISSION: i32 = 2;
    23→    const ERR_IO:         i32 = 3;
    24→    const ERR_INVALID:    i32 = 4;
    25→
    26→    // === 데이터 구조체 ===
    27→    // 파일 작업 결과 컨텍스트
    28→    struct FileResult {
    29→        success:          bool;
    30→        error_code:       i32;
    31→        bytes_processed:  u64;
    32→    }
    33→
    34→    // 디렉토리 항목 (list_dir 반환값)
    35→    struct DirEntry {
    36→        name:   string;
    37→        is_dir: bool;
    38→        size:   u64;
    39→    }
    40→
    41→    // === 내부 헬퍼 함수 ===
    42→    // '\n'을 기준으로 문자열을 라인으로 분할
    43→    @inline
    44→    func split_lines(content: string) -> [string] {
    45→        let lines = make([string], 0);
    46→        let current = "";
    47→        let i = 0;
    48→        let len = 0;
    49→
    50→        // 문자열 길이 계산 루프 (FreeLang에 strlen 내장함수 가정)
    51→        // Note: 실제 구현에서는 strlen(content) 호출 또는 런타임 제공 함수 사용
    52→        // 여기서는 간편하게 문자열 순회 시뮬레이션
    53→
    54→        // 간단한 구현: 공백으로 분할 (개선 여지 있음)
    55→        // TODO: 실제 문자 단위 순회 필요
    56→        lines.push(content);  // 임시: 전체 라인 반환
    57→        return lines;
    58→    }
    59→
    60→    // === 시스템 브리지 함수 (런타임 오버라이드 지점) ===
    61→    // 이 함수들은 런타임이 실제 OS 시스템 콜로 대체해야 함
    62→
    63→    // Linux: open(path, O_RDONLY), read(fd, buf, size), close(fd)
    64→    func sys_read_file(path: string) -> (string, i32) {
    65→        // 모의 구현: 파일을 읽지 못함
    66→        // 실제 구현은 런타임이 제공해야 함
    67→        if len(path) == 0 {
    68→            return ("", ERR_INVALID);
    69→        }
    70→        // 기본적으로 파일을 찾을 수 없다고 시뮬레이션
    71→        return ("", ERR_NOT_FOUND);
    72→    }
    73→
    74→    // Linux: open(path, O_WRONLY|O_CREAT), write(fd, buf, size), close(fd)
    75→    func sys_write_file(path: string, content: string, append: bool) -> i32 {
    76→        if len(path) == 0 {
    77→            return ERR_INVALID;
    78→        }
    79→        // 모의 구현: 항상 성공
    80→        return ERR_OK;
    81→    }
    82→
    83→    // Linux: access(path, F_OK)
    84→    func sys_file_exists(path: string) -> bool {
    85→        if len(path) == 0 {
    86→            return false;
    87→        }
    88→        return false;  // 모의 구현
    89→    }
    90→
    91→    // Linux: opendir(path), readdir(), closedir()
    92→    func sys_list_dir(path: string) -> ([string], i32) {
    93→        if len(path) == 0 {
    94→            return (make([string], 0), ERR_INVALID);
    95→        }
    96→        return (make([string], 0), ERR_NOT_FOUND);
    97→    }
    98→
    99→    // === 공개 API ===
   100→
   101→    // path에서 파일 내용 전체 읽기
   102→    // 성공: (content, true), 실패: ("", false)
   103→    func read_file(path: string) -> (string, bool) {
   104→        if len(path) == 0 {
   105→            return ("", false);
   106→        }
   107→        let content, err = sys_read_file(path);
   108→        return (content, err == ERR_OK);
   109→    }
   110→
   111→    // path에 content를 쓰기 (덮어쓰기)
   112→    func write_file(path: string, content: string) -> bool {
   113→        if len(path) == 0 {
   114→            return false;
   115→        }
   116→        let err = sys_write_file(path, content, false);
   117→        return err == ERR_OK;
   118→    }
   119→
   120→    // path에 content를 덧붙이기
   121→    func append_file(path: string, content: string) -> bool {
   122→        if len(path) == 0 {
   123→            return false;
   124→        }
   125→        let err = sys_write_file(path, content, true);
   126→        return err == ERR_OK;
   127→    }
   128→
   129→    // path 파일 존재 여부 확인
   130→    func file_exists(path: string) -> bool {
   131→        if len(path) == 0 {
   132→            return false;
   133→        }
   134→        return sys_file_exists(path);
   135→    }
   136→
   137→    // path 파일을 읽고 줄별로 분할
   138→    // '\n'을 기준으로 분할하여 [string] 배열로 반환
   139→    func read_lines(path: string) -> ([string], bool) {
   140→        if len(path) == 0 {
   141→            return (make([string], 0), false);
   142→        }
   143→        let content, ok = read_file(path);
   144→        if !ok {
   145→            return (make([string], 0), false);
   146→        }
   147→        let lines = split_lines(content);
   148→        return (lines, true);
   149→    }
   150→
   151→    // path 디렉토리의 항목 목록 조회
   152→    // 성공: ([항목들], true), 실패: ([], false)
   153→    func list_dir(path: string) -> ([string], bool) {
   154→        if len(path) == 0 {
   155→            return (make([string], 0), false);
   156→        }
   157→        let entries, err = sys_list_dir(path);
   158→        return (entries, err == ERR_OK);
   159→    }
   160→
   161→    // === 경로 조작 헬퍼 ===
   162→
   163→    // dir과 file을 경로로 결합
   164→    // 예: join_path("/data", "config.json") → "/data/config.json"
   165→    func join_path(dir: string, file: string) -> string {
   166→        if len(dir) == 0 {
   167→            return file;
   168→        }
   169→        if len(file) == 0 {
   170→            return dir;
   171→        }
   172→        // dir이 "/"로 끝나는지 확인 필요 (문자 인덱싱 미지원 가정)
   173→        // 간단한 구현: 항상 "/" 추가
   174→        return dir + "/" + file;
   175→    }
   176→
   177→    // path에서 마지막 "/"까지의 디렉토리 부분 추출
   178→    // 예: basename("/data/config.json") → "config.json"
   179→    func basename(path: string) -> string {
   180→        if len(path) == 0 {
   181→            return "";
   182→        }
   183→        // "/" 기준으로 마지막 세그먼트 반환
   184→        // TODO: 실제 문자 인덱싱 필요
   185→        return path;  // 임시 구현
   186→    }
   187→
   188→    // path에서 마지막 "/" 이전 부분 추출
   189→    // 예: dirname("/data/config.json") → "/data"
   190→    func dirname(path: string) -> string {
   191→        if len(path) == 0 {
   192→            return "";
   193→        }
   194→        // "/" 기준으로 마지막 세그먼트 제거
   195→        // TODO: 실제 문자 인덱싱 필요
   196→        return path;  // 임시 구현
   197→    }
   198→
   199→    // === 정보성 함수 ===
   200→
   201→    // FileResult 구조체를 문자열로 변환 (디버그용)
   202→    func (fr: *FileResult) to_string() -> string {
   203→        let status = if fr.success { "OK" } else { "FAIL" };
   204→        let msg = "[FileResult] status=" + status + " error_code=" + i32_to_string(fr.error_code) + " bytes=" + u64_to_string(fr.bytes_processed);
   205→        return msg;
   206→    }
   207→
   208→    // i32를 문자열로 변환 (헬퍼)
   209→    @inline
   210→    func i32_to_string(n: i32) -> string {
   211→        // Note: 런타임이 제공하는 내장 함수 또는 직접 구현 필요
   212→        if n == 0 { return "0"; }
   213→        if n == 1 { return "1"; }
   214→        if n == 2 { return "2"; }
   215→        if n == 3 { return "3"; }
   216→        if n == 4 { return "4"; }
   217→        return "?";
   218→    }
   219→
   220→    // u64를 문자열로 변환 (헬퍼)
   221→    @inline
   222→    func u64_to_string(n: u64) -> string {
   223→        return "0x" + i32_to_string(i32(n));
   224→    }
   225→}
   226→
   227→// === 테스트 시나리오 (주석) ===
   228→// 기본 동작:
   229→//   - read_file("nonexistent") → ("", false)
   230→//   - write_file("/tmp/test.txt", "hello") → true (모의)
   231→//   - file_exists("/tmp/test.txt") → false (모의)
   232→//   - read_lines("/tmp/words.txt") → ([], false) (파일 없음)
   233→//   - list_dir("/tmp") → ([], false) (모의)
   234→//   - join_path("/data", "config.json") → "/data/config.json"
   235→//
   236→// 런타임 통합 시:
   237→//   - sys_read_file, sys_write_file, sys_file_exists, sys_list_dir을
   238→//     실제 OS 시스템 콜로 오버라이드하면 동작 활성화됨
