   384→        print("╔════════════════════════════════════════╗");
   385→        print("║ VectorCore SoA Statistics              ║");
   386→        print("╠════════════════════════════════════════╣");
   387→        print("║ Vector Count:  " + s.count);
   388→        print("║ Capacity:      " + s.capacity);
