   310→    // virtual_alloc: 메모리 할당 (모의)
   311→    func virtual_alloc(size: u32) -> u64 {
   312→        // 실제 구현에서는:
   313→        // - Linux: malloc() 또는 aligned_alloc()
   314→        // - Windows: VirtualAlloc()
   315→        // - MacOS: malloc_aligned()
   316→
   317→        // 여기서는 임의의 주소 반환 (테스트용)
   318→        return u64(size);
   319→    }
